/*
 * A277947  Squares whose largest decimal digit is 3.
 * https://oeis.org/A277947
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, base
 * Formula:   a(n) is the n-th positive square whose decimal representation *
 *            contains only the digits 0,1,2,3 and includes at least one digit
 *            3. * The values are generated by linear search over natural
 *            numbers
 * Range:     u8 none, u16 n <= 1, u32 n <= 20, u64 n <= 100, u128 n <= 100,
 *            big any n
 * Helpers:   has_digit_three_lt_or_equal_three
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include "../utils/has_digit_three_lt_or_equal_three.h"

static seq_t *cache = NULL;          /* cache of found squares */
static size_t  cache_len = 0;        /* number of cached terms */
static size_t  cache_cap = 0;        /* allocated capacity */
static idx_t   next_root = 1;        /* next integer to test */

/* ensure cache has capacity >= needed */
static void ensure_cache_capacity(size_t needed)
{
    if (cache_cap < needed) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 1024;
        if (new_cap < needed) new_cap = needed;
        seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!new_cache) abort(); /* simple error handling */
        cache = new_cache;
        cache_cap = new_cap;
    }
}

static void add_cache(seq_t val)
{
    if (cache_len == cache_cap) ensure_cache_capacity(cache_cap + 1);
    cache[cache_len++] = val;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0; /* undefined for offset 1, but safe return */

    /* generate terms until we have at least n cached */
    while (cache_len < n) {
        seq_t root = (seq_t)next_root;
        seq_t sq   = root * root;
        if (has_digit_three_lt_or_equal_three(sq)) add_cache(sq);
        ++next_root;
    }
    return cache[n - 1];
}
